86	void PhysicsContact::generateContactData()
87	{
88	    if (_contactInfo == nullptr)
89	    {
90	        return;
91	    }
92	
93	    cpArbiter* arb = static_cast<cpArbiter*>(_contactInfo);
94	    CC_SAFE_DELETE(_preContactData);
95	    _preContactData = _contactData;
96	    _contactData = new (std::nothrow) PhysicsContactData();
97	
98	    cpContactPointSet contactSet = cpArbiterGetContactPointSet(arb);
99	    _contactData->count = contactSet.count > PhysicsContactData::POINT_MAX ? PhysicsContactData::POINT_MAX : contactSet.count;
100	
101	    for (int i = 0; i < _contactData->count; ++i)
102	    {
103	        _contactData->points[i] = PhysicsHelper::cpv2point(contactSet.points[i].pointA);
104	    }
105	
106	    _contactData->normal = _contactData->count > 0 ? PhysicsHelper::cpv2point(contactSet.normal) : Vec2::ZERO;
107	}
