199	void EventListenerPhysicsContact::onEvent(EventCustom* event)
200	{
201	    PhysicsContact* contact = dynamic_cast<PhysicsContact*>(event);
202	    if (contact == nullptr)
203	    {
204	        return;
205	    }
206	
207	    switch (contact->getEventCode())
208	    {
209	        case PhysicsContact::EventCode::BEGIN:
210	        {
211	            bool ret = true;
212	
213	            if (onContactBegin != nullptr
214	                && hitTest(contact->getShapeA(), contact->getShapeB()))
215	            {
216	                contact->generateContactData();
217	                ret = onContactBegin(*contact);
218	            }
219	
220	            contact->setResult(ret);
221	            break;
222	        }
223	        case PhysicsContact::EventCode::PRESOLVE:
224	        {
225	            bool ret = true;
226	
227	            if (onContactPreSolve != nullptr
228	                && hitTest(contact->getShapeA(), contact->getShapeB()))
229	            {
230	                PhysicsContactPreSolve solve(contact->_contactInfo);
231	                contact->generateContactData();
232	
233	                ret = onContactPreSolve(*contact, solve);
234	            }
235	
236	            contact->setResult(ret);
237	            break;
238	        }
239	        case PhysicsContact::EventCode::POSTSOLVE:
240	        {
241	            if (onContactPostSolve != nullptr
242	                && hitTest(contact->getShapeA(), contact->getShapeB()))
243	            {
244	                PhysicsContactPostSolve solve(contact->_contactInfo);
245	                onContactPostSolve(*contact, solve);
246	            }
247	            break;
248	        }
249	        case PhysicsContact::EventCode::SEPARATE:
250	        {
251	            if (onContactSeparate != nullptr
252	                && hitTest(contact->getShapeA(), contact->getShapeB()))
253	            {
254	                onContactSeparate(*contact);
255	            }
256	            break;
257	        }
258	        default:
259	            break;
260	    }
261	}
